class Playlist:
    def __init__(self, name, songs):
        self.name = name
        self.songs = songs

    def __str__(self):
        return f'{self.name} ({len(self.songs)} songs)'

    def __len__(self):
        return len(self.songs)

    def __eq__(self, other):
        return self.songs == other.songs

    def __call__(self, i):
        return self.songs[i]
